package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_previousElementSibling_TriageGen2Test {

    @Test
    public void testPreviousElementSibling_WithPreviousSibling() {
        // Setup: <div><p>1</p><p>2</p></div>
        Document doc = Parser.parseHtml("<div><p>1</p><p>2</p></div>");
        Element secondP = doc.select("p").get(1);
        Element firstP = doc.select("p").get(0);

        Element result = secondP.previousElementSibling();

        assertNotNull(result);
        assertEquals(firstP, result);
    }

    @Test
    public void testPreviousElementSibling_WhenFirstChild() {
        // Setup: <div><p>1</p><p>2</p></div>
        Document doc = Parser.parseHtml("<div><p>1</p><p>2</p></div>");
        Element firstP = doc.select("p").get(0);

        Element result = firstP.previousElementSibling();

        assertNull(result);
    }

    @Test
    public void testPreviousElementSibling_WithComplexStructure() {
        // Setup: <ul><li>A</li><li>B</li><li>C</li></ul>
        Document doc = Parser.parseHtml("<ul><li>A</li><li>B</li><li>C</li></ul>");
        Element elementB = doc.select("li").get(1);
        Element elementA = doc.select("li").get(0);

        Element result = elementB.previousElementSibling();

        assertNotNull(result);
        assertEquals("li", result.tagName());
        assertEquals(elementA, result);
    }

    @Test
    public void testPreviousElementSibling_SingleChild() {
        // Setup: <div><p>1</p></div>
        Document doc = Parser.parseHtml("<div><p>1</p></div>");
        Element singleP = doc.select("p").get(0);

        Element result = singleP.previousElementSibling();

        assertNull(result);
    }
}
